Definition w4hdi (L p bits : Z) : Prop := 0 <= p /\ (p = 0 \/ p + 8 <= L) /\ 0 <= bits <= 64 /\ (8 <= p -> bits <= 8).

Lemma w4s1_tr : forall m m' A cs W, rw_cells asegs m A cs -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W A (Z.of_nat (cells_size cs)) -> rw_cells asegs m' A cs.
Proof.
